            .@"epsilon" => 90,
            .@"kw_via" => 91,
            .@"label" => 94,
            .@"kw_left" => 96,
            .@"kw_right" => 97,
            .@"kw_none" => 98,
            .@"kw_wrapper" => 100,
            .@"union" => 103,
